"""German HTML shell and fixed local browser-script loading."""
from pathlib import Path

CLIENT_SCRIPT_PATH = Path(__file__).with_name("static") / "client.js"

def client_script():
    """Read the single packaged client; request paths never select a file."""
    return CLIENT_SCRIPT_PATH.read_text(encoding="utf-8")

